WITH unpacked AS (SELECT id, effective_from, currency, tier_limits, tier_prices, discounts, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers) SELECT DATE_TRUNC('MONTH', effective_from) AS activity_month, currency, COUNT_IF(currency = 'USD') AS usd_events, AVG(avg_tier_price) FILTER (WHERE currency = 'USD') AS usd_avg_avg_tier_price FROM unpacked GROUP BY activity_month, currency;
